import { NextRequest, NextResponse } from "next/server";
import dbConnect from "@/lib/db";
import AdLeadCrm from "@/models/AdLeadCrm";
import { checkRBAC } from "@/lib/rbac";

export const dynamic = "force-dynamic";

/**
 * GET /api/panel/ads/leads
 * Returns buyer inquiry leads generated by Meta Ads for the logged-in Builder/Mandate
 */
export async function GET(req: NextRequest) {
  try {
    const { context, errorResponse } = await checkRBAC(req, ["builder", "mandate", "teamLeader", "admin"]);
    if (errorResponse) return errorResponse;

    await dbConnect();

    const { searchParams } = new URL(req.url);
    const campaignId = searchParams.get("campaign_id");
    const propertyId = searchParams.get("property_id");
    const crmStatus = searchParams.get("status");
    const searchQuery = searchParams.get("q");

    const query: Record<string, any> = {
      owner_user_id: context!.userId,
    };

    if (campaignId) query.campaign_id = campaignId;
    if (propertyId) query.root_property_id = propertyId;
    if (crmStatus && crmStatus !== "ALL") query.crm_status = crmStatus;

    if (searchQuery) {
      query.$or = [
        { buyer_full_name: { $regex: searchQuery, $options: "i" } },
        { buyer_phone: { $regex: searchQuery, $options: "i" } },
        { buyer_email: { $regex: searchQuery, $options: "i" } },
        { hierarchy_breadcrumb: { $regex: searchQuery, $options: "i" } },
      ];
    }

    const leads = await AdLeadCrm.find(query)
      .sort({ createdAt: -1 })
      .lean();

    return NextResponse.json({
      success: true,
      count: leads.length,
      leads,
    });
  } catch (error: any) {
    console.error("[GET /api/panel/ads/leads] error:", error);
    return NextResponse.json({ success: false, error: error.message }, { status: 500 });
  }
}
